package com.luminor.tavernquest.di
import android.content.Context;import androidx.room.Room;import com.luminor.tavernquest.data.local.database.*;import dagger.Module;import dagger.Provides;import dagger.hilt.InstallIn;import dagger.hilt.android.qualifiers.ApplicationContext;import dagger.hilt.components.SingletonComponent;import javax.inject.Singleton
@Module @InstallIn(SingletonComponent::class) object DatabaseModule{@Provides @Singleton fun db(@ApplicationContext c:Context)=Room.databaseBuilder(c,TavernQuestDatabase::class.java,DatabaseConstants.NAME).addMigrations(DatabaseMigrations.MIGRATION_1_2,DatabaseMigrations.MIGRATION_2_3,DatabaseMigrations.MIGRATION_3_4,DatabaseMigrations.MIGRATION_4_5,DatabaseMigrations.MIGRATION_5_6,DatabaseMigrations.MIGRATION_6_7).build();@Provides fun hero(db:TavernQuestDatabase)=db.heroDao();@Provides fun tavern(db:TavernQuestDatabase)=db.tavernDao();@Provides fun member(db:TavernQuestDatabase)=db.tavernMemberDao();@Provides fun templates(db:TavernQuestDatabase)=db.contractTemplateDao();@Provides fun daily(db:TavernQuestDatabase)=db.dailyContractDao();@Provides fun completion(db:TavernQuestDatabase)=db.questCompletionDao();@Provides fun xp(db:TavernQuestDatabase)=db.xpLedgerDao();@Provides fun activity(db:TavernQuestDatabase)=db.activityDao();@Provides fun tavernFeed(db:TavernQuestDatabase)=db.tavernFeedDao()}
